def scs_memo(a, b):
    memo = {}

    def f(i, j):
        if (i, j) not in memo:
            if i == 0:
                memo[i, j] = b[:j]
            elif j == 0:
                memo[i, j] = a[:i]
            elif a[i - 1] == b[j - 1]:
                memo[i, j] = f(i - 1, j - 1) + a[i - 1]
            else:
                left, up = f(i - 1, j), f(i, j - 1)
                memo[i, j] = left + a[i - 1] if len(left) <= len(up) else up + b[j - 1]
        return memo[i, j]

    return f(len(a), len(b))
