def dist_rec(s, t):
    def f(i, j):
        if j == len(t):
            return 1
        if i == len(s):
            return 0
        ways = f(i + 1, j)
        if s[i] == t[j]:
            ways += f(i + 1, j + 1)
        return ways
    return f(0, 0)
