``` {.python .cell-code}
def inter_rec(a, b, c):
    if len(a) + len(b) != len(c):
        return False

    def f(i, j):
        if i == len(a) and j == len(b):
            return True
        k = i + j
        if i < len(a) and a[i] == c[k] and f(i + 1, j):
            return True
        if j < len(b) and b[j] == c[k] and f(i, j + 1):
            return True
        return False

    return f(0, 0)
```
