def inter_tab(a, b, c):
    if len(a) + len(b) != len(c):
        return False
    n, m = len(a), len(b)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(n + 1):
        for j in range(m + 1):
            if i and dp[i - 1][j] and a[i - 1] == c[i + j - 1]:
                dp[i][j] = True
            if j and dp[i][j - 1] and b[j - 1] == c[i + j - 1]:
                dp[i][j] = True
    return dp[n][m]
```
