``` {.python .cell-code}
def wild_rec(s, p):
    def f(i, j):
        if j == len(p):
            return i == len(s)
        if p[j] == "*":
            if f(i, j + 1):
                return True
            return i < len(s) and f(i + 1, j)
        if i < len(s) and (p[j] == "?" or p[j] == s[i]):
            return f(i + 1, j + 1)
        return False
    return f(0, 0)
```
