def wild_greedy(s, p):
    i = j = 0
    star = match = -1
    while i < len(s):
        if j < len(p) and (p[j] == "?" or p[j] == s[i]):
            i += 1
            j += 1
        elif j < len(p) and p[j] == "*":
            star, match = j, i
            j += 1
        elif star != -1:
            match += 1
            i, j = match, star + 1
        else:
            return False
    while j < len(p) and p[j] == "*":
        j += 1
    return j == len(p)

