``` {.python .cell-code}
def regex_rec(s, p):
    def fits(i, j):
        return i < len(s) and (p[j] == "." or p[j] == s[i])

    def f(i, j):
        if j == len(p):
            return i == len(s)
        star = j + 1 < len(p) and p[j + 1] == "*"
        if star:
            if f(i, j + 2):
                return True
            return fits(i, j) and f(i + 1, j)
        return fits(i, j) and f(i + 1, j + 1)

    return f(0, 0)
```
