``` {.python .cell-code}
def _bracket_go(s):
    pi = prefix_function(s)
    m = len(s)
    go = [[0, 0] for _ in range(m + 1)]
    for state in range(m):
        for bit, ch in enumerate("()"):
            k = state
            while k and s[k] != ch:
                k = pi[k - 1]
            if s[k] == ch:
                k += 1
            go[state][bit] = k
    go[m][0] = go[m][1] = m
    return go

def bracket_rec(n, s):
    go = _bracket_go(s)
    m = len(s)

    def f(i, b, k):
        if i == 2 * n:
            return 1 if b == 0 and k == m else 0
        ways = 0
        if b + 1 <= n:
            ways += f(i + 1, b + 1, go[k][0])
        if b:
            ways += f(i + 1, b - 1, go[k][1])
        return ways % MOD

    return f(0, 0, 0)
```
:::


