``` {.python .cell-code}
def _evil_go(evil):
    pi = prefix_function(evil)
    m = len(evil)
    go = [[0] * 26 for _ in range(m + 1)]
    for state in range(m):
        for c in range(26):
            ch = chr(c + 97)
            k = state
            while k and evil[k] != ch:
                k = pi[k - 1]
            if evil[k] == ch:
                k += 1
            go[state][c] = k
    return go

def good_memo(n, s1, s2, evil):
    go = _evil_go(evil)
    m = len(evil)

    @lru_cache(None)
    def f(i, k, lo, hi):
        if k == m:
            return 0
        if i == n:
            return 1
        left = ord(s1[i]) - 97 if lo else 0
        right = ord(s2[i]) - 97 if hi else 25
        ans = 0
        for c in range(left, right + 1):
            nk = go[k][c]
            if nk == m:
                continue
            ans = (ans + f(i + 1, nk, lo and c == left, hi and c == right)) % MOD
        return ans

    return f(0, 0, 1, 1)
```
